typedef int int32;

class PhysicsObjectClass;

typedef void (*OdeDerivFunc)(PhysicsObjectClass* phyobj, float rTime,
   float* rInStateArray, float* rOutStateArray);

class OdeSolverClass
{
public:
	virtual ~OdeSolverClass() { };

	virtual int32 Init(int d, float step, OdeDerivFunc dfn) = 0;
	virtual int32 Terminate() = 0;
	virtual int32 Update(PhysicsObjectClass* phyobj, float timein, float *inArray, float *timeout, float *outArray) = 0;
	virtual void SetStepSize(float dt) { stepSize = dt;}

protected:
	int32			dim;
	float			stepSize;
	OdeDerivFunc	fnDerivFunc;
};

class RungeKuttaClass : public OdeSolverClass
{
public:
	int32 Init(int d, float step, OdeDerivFunc dfn);
	int32 Terminate();
	int32 Update(PhysicsObjectClass* phyobj, float timein, float *inArray, float *timeout, float *outArray);

	virtual void SetStepSize(float dt)
	{
		this->stepSize = dt;
		this->step2 = dt/2.0f;
		this->step6 = dt/6.0f;
	}

private:
   float step2, step6;
   float* temp1;
   float* temp2;
   float* temp3;
   float* temp4;
   float* xtemp;
};

int32 RungeKuttaClass::Update(PhysicsObjectClass* phyobj, float timein, float *inArray, float *timeout, float *outArray)
{

	int32 i;
	float timeHalf;

   // first step
   (this->fnDerivFunc)(phyobj, timein, inArray, this->temp1);

   for (i = 0; i < this->dim; i++)
   {
      this->xtemp[i] = inArray[i] + this->step2 * this->temp1[i];
   }


   // second step
   timeHalf = timein + this->step2;
   (this->fnDerivFunc)(phyobj, timeHalf, this->xtemp, this->temp2);

   for (i = 0; i < this->dim; i++)
   {
      this->xtemp[i] = inArray[i] + this->step2 * this->temp2[i];
   }


   // third step
   (this->fnDerivFunc)(phyobj, timeHalf, this->xtemp, this->temp3);
   for (i = 0; i < this->dim; i++)
   {
      this->xtemp[i] = inArray[i] + this->stepSize * this->temp3[i];
   }


   // fourth step
   *timeout = timein + this->stepSize;
   (this->fnDerivFunc)(phyobj, *timeout, this->xtemp, this->temp4);
   for (i = 0; i < this->dim; i++)
   {
      outArray[i] = inArray[i] +
         this->step6 * (this->temp1[i] + 2.0f * (this->temp2[i] + this->temp3[i]) + this->temp4[i]);
   }

   return 1;

}
